<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3';
import { computed } from 'vue';
import { useI18n } from 'vue-i18n';
import Breadcrumbs from '../../../../components/admin/Breadcrumbs.vue';
import EmptyState from '../../../../components/admin/EmptyState.vue';
import PageHeader from '../../../../components/admin/PageHeader.vue';
import FieldError from '../../../../components/FieldError.vue';
import AdminLayout from '../../../../layouts/AdminLayout.vue';

interface Location { id: string; name: string; code: string }
interface Variant { id: string; product_name: string; name: string | null; sku: string }
const props = defineProps<{ locations: Location[]; variants: Variant[] }>();
const form = useForm({ source_location_id: '', destination_location_id: '', notes: '', lines: [{ product_variant_id: '', quantity: 1 }] });
const { t } = useI18n();
const canTransfer = computed(() => props.locations.length >= 2 && props.variants.length > 0);
const addLine = () => form.lines.push({ product_variant_id: '', quantity: 1 });
const removeLine = (index: number) => form.lines.splice(index, 1);
const submit = () => { if (!form.processing && canTransfer.value) form.post('/admin/inventory/transfers'); };
const fieldError = (field: string) => {
    const errors = form.errors as Record<string, string | undefined>;
    return errors[field] ? t(`inventory.transfer.errors.${field.replace(/\.\d+\./u, '.')}`) : undefined;
};
</script>

<template>
    <Head :title="t('inventory.transfer.title')" />
    <AdminLayout><section class="mx-auto grid w-full max-w-5xl gap-5 sm:gap-6">
        <Breadcrumbs :items="[{ label: t('nav.operations') }, { label: t('inventory.title'), href: '/admin/inventory' }, { label: t('inventory.transfer.title') }]" />
        <PageHeader :title="t('inventory.transfer.title')" :eyebrow="t('common.allCompany')" :description="t('inventory.transfer.description')"><template #actions><Link href="/admin/inventory" class="inline-flex min-h-9 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold text-admin-text-secondary hover:bg-slate-50">{{ t('inventory.back') }}</Link></template></PageHeader>
        <aside class="flex gap-3 rounded-md border border-admin-info-border bg-admin-info-bg px-4 py-3"><div><p class="text-sm font-semibold text-admin-text">{{ t('inventory.transfer.atomicTitle') }}</p><p class="mt-0.5 text-xs leading-5 text-admin-text-secondary">{{ t('inventory.transfer.atomicHelp') }}</p></div></aside>
        <EmptyState v-if="!canTransfer" :title="t('inventory.transfer.unavailable')" :description="locations.length < 2 ? t('inventory.transfer.locationsRequired') : t('inventory.transfer.variantsRequired')"><template #actions><Link v-if="locations.length < 2" href="/admin/inventory/locations/create" class="admin-link text-sm">{{ t('inventory.locations.create') }}</Link></template></EmptyState>
        <form v-else class="grid gap-5" @submit.prevent="submit"><section class="admin-card overflow-hidden"><header class="border-b border-admin-border px-5 py-4 sm:px-6"><p class="admin-label text-admin-secondary">{{ t('inventory.transfer.routeSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('inventory.transfer.route') }}</h2><p class="mt-1 text-xs text-admin-neutral">{{ t('inventory.transfer.routeHelp') }}</p></header><div class="grid gap-5 p-5 sm:p-6 md:grid-cols-2"><div><label for="transfer-source" class="mb-1.5 block text-sm font-semibold">{{ t('inventory.transfer.from') }} <span class="text-admin-danger">*</span></label><select id="transfer-source" v-model="form.source_location_id" required class="admin-control w-full px-3 text-sm" :aria-invalid="Boolean(form.errors.source_location_id)"><option value="">{{ t('inventory.transfer.selectSource') }}</option><option v-for="location in locations" :key="location.id" :value="location.id">{{ location.name }} · {{ location.code }}</option></select><FieldError :message="fieldError('source_location_id')" /></div><div><label for="transfer-destination" class="mb-1.5 block text-sm font-semibold">{{ t('inventory.transfer.to') }} <span class="text-admin-danger">*</span></label><select id="transfer-destination" v-model="form.destination_location_id" required class="admin-control w-full px-3 text-sm" :aria-invalid="Boolean(form.errors.destination_location_id)"><option value="">{{ t('inventory.transfer.selectDestination') }}</option><option v-for="location in locations" :key="location.id" :value="location.id" :disabled="location.id === form.source_location_id">{{ location.name }} · {{ location.code }}</option></select><FieldError :message="fieldError('destination_location_id')" /></div><div class="md:col-span-2"><label for="transfer-notes" class="mb-1.5 block text-sm font-semibold">{{ t('inventory.transfer.notes') }} <span class="font-normal text-admin-neutral">({{ t('common.optional') }})</span></label><textarea id="transfer-notes" v-model="form.notes" rows="3" maxlength="2000" class="admin-control w-full px-3 py-2 text-sm" :aria-invalid="Boolean(form.errors.notes)" /><FieldError :message="fieldError('notes')" /></div></div></section>
            <section class="admin-card overflow-hidden"><header class="flex flex-col gap-3 border-b border-admin-border px-5 py-4 sm:flex-row sm:items-center sm:justify-between sm:px-6"><div><p class="admin-label text-admin-secondary">{{ t('inventory.transfer.linesSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('inventory.transfer.lines') }}</h2><p class="mt-1 text-xs text-admin-neutral">{{ t('inventory.transfer.linesHelp') }}</p></div><button type="button" class="min-h-9 rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold text-admin-text-secondary hover:bg-slate-50" @click="addLine">{{ t('inventory.transfer.addLine') }}</button></header><FieldError v-if="form.errors.lines" class="px-5 pt-3" :message="fieldError('lines')" /><div class="grid gap-3 p-3 sm:p-5"><div v-for="(line, index) in form.lines" :key="index" class="grid gap-3 rounded-md border border-admin-border bg-admin-canvas p-3 sm:grid-cols-[minmax(0,1fr)_9rem_auto] sm:items-start"><div><label :for="`variant-${index}`" class="mb-1.5 block text-xs font-semibold">{{ t('inventory.transfer.variant') }} <span class="text-admin-danger">*</span></label><select :id="`variant-${index}`" v-model="line.product_variant_id" required class="admin-control w-full px-3 text-sm" :aria-invalid="Boolean(form.errors[`lines.${index}.product_variant_id`])"><option value="">{{ t('inventory.transfer.selectVariant') }}</option><option v-for="variant in variants" :key="variant.id" :value="variant.id">{{ variant.product_name }} · {{ variant.sku }}<template v-if="variant.name"> · {{ variant.name }}</template></option></select><FieldError :message="fieldError(`lines.${index}.product_variant_id`)" /></div><div><label :for="`quantity-${index}`" class="mb-1.5 block text-xs font-semibold">{{ t('inventory.quantity') }} <span class="text-admin-danger">*</span></label><input :id="`quantity-${index}`" v-model.number="line.quantity" required type="number" min="1" step="1" class="admin-control w-full px-3 font-mono text-sm" :aria-invalid="Boolean(form.errors[`lines.${index}.quantity`])" /><FieldError :message="fieldError(`lines.${index}.quantity`)" /></div><button v-if="form.lines.length > 1" type="button" class="min-h-9 rounded-md px-3 text-xs font-semibold text-admin-danger hover:bg-admin-danger-bg sm:mt-6" :aria-label="t('inventory.transfer.removeLineNumber', { number: index + 1 })" @click="removeLine(index)">{{ t('common.remove') }}</button></div></div></section>
            <footer class="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><Link href="/admin/inventory" class="inline-flex min-h-10 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold text-admin-text-secondary">{{ t('common.cancel') }}</Link><button type="submit" :disabled="form.processing" class="min-h-10 rounded-md bg-admin-primary px-5 text-sm font-semibold text-white disabled:opacity-60">{{ form.processing ? t('inventory.transfer.transferring') : t('inventory.transfer.submit') }}</button></footer></form>
    </section></AdminLayout>
</template>
